-- Sprint 4 #23/#24. Empty schema by design: no fictional data or default catalogue rows.
CREATE TABLE design_styles (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(100) NOT NULL CHECK (length(btrim(name))>0));
CREATE UNIQUE INDEX design_styles_name_ci_uq ON design_styles(lower(btrim(name)));
CREATE TABLE property_types (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(100) NOT NULL CHECK (length(btrim(name))>0));
CREATE UNIQUE INDEX property_types_name_ci_uq ON property_types(lower(btrim(name)));
CREATE TABLE size_ranges (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(100) NOT NULL CHECK (length(btrim(name))>0), min_sqm NUMERIC(10,2), max_sqm NUMERIC(10,2), CONSTRAINT size_ranges_bounds CHECK ((min_sqm IS NULL OR min_sqm >= 0) AND (max_sqm IS NULL OR max_sqm > 0) AND (min_sqm IS NULL OR max_sqm IS NULL OR min_sqm < max_sqm)));
CREATE UNIQUE INDEX size_ranges_name_ci_uq ON size_ranges(lower(btrim(name)));
-- The GiST exclusion constraint also protects against concurrent overlapping edits.
ALTER TABLE size_ranges ADD CONSTRAINT size_ranges_no_overlap EXCLUDE USING gist (numrange(COALESCE(min_sqm,0),max_sqm,'[)') WITH &&);
CREATE TABLE project_metadata (project_id BIGINT PRIMARY KEY REFERENCES interior_design_projects(id) ON DELETE CASCADE, property_type_id BIGINT REFERENCES property_types(id) ON DELETE SET NULL, floor_area_sqm NUMERIC(10,2) CHECK(floor_area_sqm IS NULL OR floor_area_sqm>0));
CREATE TABLE project_design_styles (project_id BIGINT NOT NULL REFERENCES interior_design_projects(id) ON DELETE CASCADE, style_id BIGINT NOT NULL REFERENCES design_styles(id) ON DELETE CASCADE, role VARCHAR(16) NOT NULL CHECK (role IN ('PRIMARY','SECONDARY')), PRIMARY KEY(project_id,style_id));
CREATE UNIQUE INDEX project_design_primary_uq ON project_design_styles(project_id) WHERE role='PRIMARY';
CREATE TABLE customer_recommendation_preferences (customer_id BIGINT PRIMARY KEY REFERENCES user_accounts(id) ON DELETE CASCADE, size_range_id BIGINT REFERENCES size_ranges(id) ON DELETE SET NULL, onboarding_state VARCHAR(16) NOT NULL DEFAULT 'PENDING' CHECK(onboarding_state IN ('PENDING','SKIPPED','COMPLETED')));
CREATE TABLE customer_preferred_categories (customer_id BIGINT REFERENCES user_accounts(id) ON DELETE CASCADE, category_id BIGINT REFERENCES project_categories(id) ON DELETE CASCADE, PRIMARY KEY(customer_id,category_id));
CREATE TABLE customer_preferred_styles (customer_id BIGINT REFERENCES user_accounts(id) ON DELETE CASCADE, style_id BIGINT REFERENCES design_styles(id) ON DELETE CASCADE, PRIMARY KEY(customer_id,style_id));
CREATE TABLE customer_preferred_property_types (customer_id BIGINT REFERENCES user_accounts(id) ON DELETE CASCADE, property_type_id BIGINT REFERENCES property_types(id) ON DELETE CASCADE, PRIMARY KEY(customer_id,property_type_id));
CREATE INDEX project_design_styles_style_idx ON project_design_styles(style_id);
CREATE INDEX project_metadata_property_idx ON project_metadata(property_type_id);
